record.field:
partner = tools.find("res.partner", customer_name) or record.partner_id
if not partner:
    raise UserError("La cotización necesita un cliente; la conversación no tiene uno.")
order_lines = []
for line in tools.lines(lines):
    product = tools.find("product.product", line["name"])
    label = "%s x %s %s" % (line["quantity"], line["name"], line["unit"])
    if product:
        order_lines.append((0, 0, {"product_id": product.id, "product_qty": line["quantity"],
                                   "name": product.display_name + ((" (" + line["unit"] + ")") if line["unit"] else "")}))
    else:
        order_lines.append((0, 0, {"display_type": "line_note", "name": "Por confirmar: " + label.strip()}))
order = env["sale.order"].create({
    "partner_id": partner.id,
    "user_id": record._tool_assignee().id,
    "origin": record._tool_origin(),
    "line_ids": order_lines,
})
if note:
    record._tool_note(order, note)
ai["result"] = {"model": "sale.order", "id": order.id}

{
    "type": "object",
    "properties": {
        "customer_name": {"type": "string", "description": "Vacío = cliente de la conversación"},
        "lines": {
            "type": "array",
            "items": {"type": "string"},
            "description": "Una línea por producto con el formato 'producto | cantidad | unidad dicha', p. ej. 'Proxity | 2 | cajas'"
        },
        "note": {"type": "string"}
    },
    "required": ["lines"]
}
